DROP TABLE IF EXISTS `movimientos_herramientas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimientos_herramientas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `herramienta_id` int NOT NULL,
  `acta_id` int DEFAULT NULL,
  `tipo` enum('ingreso','entrega','devolucion','dano','perdida','reparacion','baja','ajuste','edicion','correccion') COLLATE utf8mb4_spanish_ci NOT NULL,
  `lote` varchar(36) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `cantidad` int NOT NULL,
  `disponible_resultante` int NOT NULL,
  `observaciones` varchar(1000) COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `usuario_id` int NOT NULL,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_movh_acta` (`acta_id`),
  KEY `fk_movh_usuario` (`usuario_id`),
  KEY `idx_movh_herr` (`herramienta_id`),
  KEY `idx_movh_fecha` (`fecha`),
  KEY `idx_movh_lote` (`lote`),
  CONSTRAINT `fk_movh_acta` FOREIGN KEY (`acta_id`) REFERENCES `actas_herramientas` (`id`),
  CONSTRAINT `fk_movh_herr` FOREIGN KEY (`herramienta_id`) REFERENCES `herramientas` (`id`),
  CONSTRAINT `fk_movh_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

